window.AUTH=window.AUTH||{};window.AUTH["17-290"]={"d":"17-290","id":"2018/17-290","n":"Merck Sharp & Dohme Corp. v. Albrecht","briefs":[{"k":"petitioner","label":"Brief of petitioner Merck Sharp & Dohme Corp.","date":"2018-09-13","url":"https://www.supremecourt.gov/DocketPDF/17/17-290/63648/20180913151659565_17-290%20ts.pdf","side":"pet","n":45},{"k":"united-states","label":"Brief amicus curiae of United States","date":"2018-09-20","url":"https://www.supremecourt.gov/DocketPDF/17/17-290/64442/20180920182839284_17-290tsacUnitedStates.pdf","side":"us","n":44},{"k":"respondent","label":"Brief of respondents Doris Albrecht, et al.","date":"2018-11-14","url":"https://www.supremecourt.gov/DocketPDF/17/17-290/72102/20181114164845977_17-290bs.pdf","side":"res","n":39},{"k":"reply","label":"Reply of petitioner Merck Sharp & Dohme Corp.","date":"2018-12-14","url":"https://www.supremecourt.gov/DocketPDF/17/17-290/76308/20181214153644658_17-290%20rb.pdf","side":"pet","n":14}],"opinion":"https://www.supremecourt.gov/opinions/18pdf/17-290_i425.pdf","tr":true,"items":[{"t":"case","label":"Addington v. Texas","cite":"441 U.S. 418","y":1979,"id":"1978/77-5992","sc":1,"sum":"The Court held that the standard of proof required in a civil case involving involuntary commitment to a mental health facility must be higher than a preponderance of the evidence, but that the “beyond a reasonable doubt” standard was not constitutionally required.","sumSrc":"Oyez","by":{"0":"45","1":"24, 25","3":"21"}},{"t":"case","label":"B&B Hardware, Inc. v. Hargis Indus., Inc.","cite":"135 S. Ct. 1293","y":2015,"id":"2014/13-352","sc":1,"sum":"The Court held that a decision on an issue by an administrative agency can preclude re-litigation of that issue in federal court.","sumSrc":"Oyez","by":{"0":"41"}},{"t":"case","label":"Block v. Cmty. Nutrition Inst.","cite":"467 U.S. 340","y":1984,"id":"1983/83-458","sc":1,"sum":"The individual consumers may not obtain judicial review of the milk market orders in question.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"46, 47","1":"26","3":"20"}},{"t":"case","label":"Boyle v. United Techs. Corp.","cite":"487 U.S. 500","y":1988,"id":"1987/86-492","sc":1,"sum":"In a 5-to4 decision, the Court held that despite the absence of specific legislation immunizing government contractors from liability for design flaws, questions of their liability are of unique federal concern. As such, to the extent that it holds military contractors liable for design flaws, state law may significantly conflict with federal interests thereby requiring its displacement.","sumSrc":"Oyez","by":{"0":"47","1":"28, 29","2":"26, 51, 52"}},{"t":"case","label":"Buckman Co. v. Plaintiffs’ Legal Comm.","cite":"531 U.S. 341","y":2001,"id":"2000/98-1768","sc":1,"sum":"The Court held that the plaintiffs' state-law fraud-on-the-FDA claims conflicted with, and were therefore pre-empted by, the FDCA, as amended by the MDA. \"The conflict,\" wrote Chief Justice Rehnquist for the Court, \"stems from the fact that the federal statutory scheme amply empowers the FDA to punish and deter fraud against the Agency, and that this authority is used by the Agency to achieve a somewhat delicate balance of statutory objectives.","sumSrc":"Oyez","by":{"0":"33, 39","1":"28"}},{"t":"case","label":"Cerveny v. Aventis, Inc.","cite":"855 F.3d 1091","y":2017,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.3d/855/1091/","by":{"0":"53","2":"44"}},{"t":"case","label":"Concrete Pipe & Prods. of Cal., Inc. v. Constr. Laborers Pension Tr. for S. Cal.","cite":"508 U.S. 602","y":1993,"id":"1992/91-904","sc":1,"sum":"The Multiemployer Pension Plan Amendments Act of 1980 (MPPAA) amended the Employee Retirement Income Security Act of 1974 (ERISA) to provide that in certain circumstances an employer withdrawing from a multiemployer plan incurs as \"withdrawal liability\" a share of the plan's unfunded vested benefits, 29 U. S. C. §§ 1381, 1391. Withdrawal liability is assessed by means of a notification by the \"plan sponsor\" and a …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"43"}},{"t":"case","label":"Dennis v. United States","cite":"341 U.S. 494","y":1951,"id":"1940-1955/341us494","sc":1,"sum":"The Court decided that the Smith Act, a federal law which made it a crime to advocate or organize for the purpose of overthrowing the government, did not violate the First Amendment of the Constitution.","sumSrc":"Oyez","by":{"0":"42"}},{"t":"case","label":"Dolin v. GlaxoSmithKline LLC, __ F. 3d __","cite":"2018 WL 4001208","y":2018,"court":"7th Cir. Aug. 22","sum":"Concluding that it would be “unreasonable” to conclude that FDA rejected a proposed warning because the manufacturer had proposed adding it to the wrong place in the labeling, rather than because FDA had concluded that the warning was not warranted.","sumSrc":"brief:1","by":{"0":"37, 53","1":"33"}},{"t":"case","label":"English v. Gen. Elec. Co.","cite":"496 U.S. 72","y":1990,"id":"1989/89-152","sc":1,"sum":"English's state-law claim for intentional infliction of emotional distress is not pre-empted by federal law.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"26","1":"26"}},{"t":"case","label":"Geier v. Am. Honda Motor Co.","cite":"529 U.S. 861","y":2000,"id":"1999/98-1811","sc":1,"sum":"The Court held that \"[Geier's] 'no airbag' lawsuit conflicts with the objectives of FMVSS 208 and is therefore pre-empted by the Act.\" Justice Breyer wrote for the Court that a rule of state tort law imposing a duty to install airbags in cars such as Honda's would have presented an obstacle to the variety and mix of devices that the federal regulation sought and to the phase-in that the federal regulation deliberately imposed.","sumSrc":"Oyez","by":{"0":"51","1":"26","2":"45","3":"15"}},{"t":"case","label":"Hillsborough Cty. v. Automated Med. Labs., Inc.","cite":"471 U.S. 707","y":1985,"id":"1984/83-1925","sc":1,"sum":"Appellant county's ordinances and implementing regulations are not pre-empted by the federal regulations.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"41"}},{"t":"case","label":"Markman v. Westview Instruments, Inc.","cite":"517 U.S. 370","y":1996,"id":"1995/95-26","sc":1,"op":4,"ar":1,"sum":"Authored by Justice David H. Souter, the Court held that the construction of a patent, including terms of art within its claim, is exclusively within the province of the court. Justice Souter wrote that \"judges, not juries, are the better suited to find the acquired meaning of patent terms.\".","sumSrc":"Oyez","by":{"0":"45","1":"15, 19","2":"53"}},{"t":"case","label":"Massachusetts v. EPA","cite":"549 U.S. 497","y":2007,"id":"2006/05-1120","sc":1,"sum":"The Court ruled that states could sue the EPA for potential damage to their territory caused by global warming, and that the Clean Air Act imposes a duty upon the EPA to regulate the emissions of carbon dioxide and other gases that contribute to global warming.","sumSrc":"Oyez","by":{"0":"44"}},{"t":"case","label":"Matsushita Elec. Indus. Co. v. Zenith Radio Corp.","cite":"475 U.S. 574","y":1986,"id":"1985/83-2004","sc":1,"sum":"The Court held that evidence of alleged conspiracies is not sufficient to prove allegations of violating antitrust legislation unless there is evidence that the conspiracies in question injured American companies.","sumSrc":"Oyez","by":{"0":"52"}},{"t":"case","label":"Microsoft Corp. v. i4i Ltd. P’ship","cite":"564 U.S. 91","y":2011,"id":"2010/10-290","sc":1,"op":1,"sum":"The Court held that a challenge to a patent's validity must offer clear and convincing evidence.","sumSrc":"Oyez","by":{"0":"43, 45","1":"24, 25"}},{"t":"case","label":"Mutual Pharm. Co. v. Bartlett","cite":"570 U.S. 472","y":2013,"id":"2012/12-142","sc":1,"op":2,"sum":"The Court found that federal law preempts state law design-defect claims.","sumSrc":"Oyez","by":{"0":"passim","1":"4","2":"46"}},{"t":"case","label":"Penn. State Police v. Suders","cite":"542 U.S. 129","y":2004,"id":"2003/03-95","sc":1,"sum":"In an 8-to-1 decision written by Justice Ruth Bader Ginsburg, the Court ruled that an employee faced with a situation in which a \"reasonable person ... would have felt compelled to resign\" could bring suit even if she had not filed a report with the employer before resigning.","sumSrc":"Oyez","by":{"0":"45"}},{"t":"case","label":"PLIVA, Inc. v. Mensing","cite":"564 U.S. 604","y":2011,"id":"2010/09-993","sc":1,"op":3,"sum":"The Court held that generic drug makers cannot be sued for not warning about potentially dangerous side effects on their drug labels, even when they follow federal rules that only require their labels to match those of their brand-name equivalents.","sumSrc":"Oyez","by":{"0":"passim","1":"4, 17, 18, 21, 23","2":"1, 2, 4, 24, 29, 30, 45, 55, 56","3":"13, 22"}},{"t":"case","label":"Reiter v. Sonotone Corp.","cite":"442 U.S. 330","y":1979,"id":"1978/78-690","sc":1,"sum":"Consumers who pay a higher price for goods purchased for personal use as a result of antitrust violations sustain an injury in their \"property\" within the meaning of § 4.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"46"}},{"t":"case","label":"Rivera v. Minnich","cite":"483 U.S. 574","y":1987,"id":"1986/86-98","sc":1,"sum":"Pennsylvania's preponderance standard for determining paternity is constitutionally permissible. The preponderance standard is applied most frequently in litigation between private parties in every State and, more specifically, is the standard that is applied in paternity litigation in the majority of American jurisdictions that regard such proceedings as civil in nature (as does Pennsylvania). Such a legislative …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"45","1":"25"}},{"t":"case","label":"Santosky v. Kramer","cite":"455 U.S. 745","y":1982,"id":"1981/80-5889","sc":1,"sum":"Under New York law, the State may terminate, over parental objection, the rights of parents in their natural child upon a finding that the child is \"permanently neglected.\" The New York Family Court Act (§ 622) requires that only a \"fair preponderance of the evidence\" support that finding. Neglect proceedings were brought in Family Court to terminate petitioners' rights as natural parents in their three children. …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"45","1":"24","3":"21"}},{"t":"case","label":"Sprietsma v. Mercury Marine","cite":"537 U.S. 51","y":2002,"id":"2002/01-706","sc":1,"sum":"The Court held 8-0 that neither the text nor the intent of the FBSA preempts Sprietsma's common law claims, either explicitly or implicitly.","sumSrc":"Oyez","by":{"0":"41","1":"20"}},{"t":"case","label":"Steadman v. SEC","cite":"450 U.S. 91","y":1981,"id":"1980/79-1266","sc":1,"sum":"After an on-the-record hearing before an Administrative Law Judge and review by the Securities and Exchange Commission (SEC) in which the preponderance-of-the-evidence standard of proof was employed, the SEC held that petitioner had violated various antifraud provisions of the federal securities laws, and sanctions were imposed. Petitioner sought review in the Court of Appeals on the alleged ground, inter alia, that …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"45"}},{"t":"case","label":"U.S. Postal Serv. v. Gregory","cite":"534 U.S. 1","y":2001,"id":"2001/00-758","sc":1,"sum":"The Court held that that the Federal Circuit's ruling was vacated because the Board has broad discretion in determining how to review prior disciplinary actions and need not adopt the Federal Circuit's rule.","sumSrc":"Oyez","by":{"0":"39, 44"}},{"t":"case","label":"United States ex rel. Touhy v. Regan","cite":"340 U.S. 462","y":1951,"id":"scdb/1950-037","sc":1,"sum":"Order No. 3229 is valid and the subordinate official properly refused to produce the papers.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"52"}},{"t":"case","label":"United States v. Chem. Found.","cite":"272 U.S. 1","y":1926,"id":"scdb/1926-001","sc":1,"op":1,"sum":"1. A decree of the Circuit Court of Appeals, entered prior to the taking effect of the Jurisdictional Act of February 13, 1925, and affirming dismissal on the merits of a bill by the United States to set aside, as unauthorized and fraudulently procured, sales of patent and other rights and properties seized pursuant to the Trading, with the Enemy Act, was reviewable by this Court on appeal (Jud. Code §§ 128, 241). …","sumSrc":"Headnote (U.S. Reports)","by":{"0":"39"}},{"t":"case","label":"Williamson v. Mazda Motor of Am., Inc.","cite":"562 U.S. 323","y":2011,"id":"2010/08-1314","sc":1,"sum":"The Court held that a wrongful death lawsuit under California law alleging that Mazda should have installed belt and shoulder seatbelts in the backseat of a minivan is not preempted by a federal regulation that gives automakers the option to install either kind of seatbelts.","sumSrc":"Oyez","by":{"0":"51"}},{"t":"case","label":"Wos v. E.M.A. ex rel. Johnson","cite":"568 U.S. 627","y":2013,"id":"2012/12-98","sc":1,"sum":"The Court held that federal law preempts North Carolina's state law regarding reimbursement of medical expenses from a patient's settlement.","sumSrc":"Oyez","by":{"0":"26"}},{"t":"case","label":"Wyeth v. Levine","cite":"555 U.S. 555","y":2009,"id":"2008/06-1249","sc":1,"op":45,"ar":4,"sum":"The Court held that federal law did not preempt state law in a personal injury action against a drug manufacturer for failing to include an appropriate warning label, even where the drug in question met the Food and Drug Administration's (FDA) labeling requirements.","sumSrc":"Oyez","by":{"0":"passim","1":"passim","2":"1, 3, 4, 6, 20, 23, 24, 28, 29, 30, 31, 32, 33, 34, 35, 38, 40, 45, 46, 47, 50, 53, 54, 55, 56","3":"passim"}},{"t":"const","label":"Article VI, Clause 2","clauses":[["supremacy","Supremacy Clause"]],"text":"This Constitution, and the Laws of the United States which shall be made in Pursuance thereof; and all Treaties made, or which shall be made, under the Authority of the United States, shall be the supreme Law of the Land; and the Judges in every State shall be bound thereby, any Thing in the Constitution or Laws of any State to the Contrary notwithstanding.","by":{"0":"26, 47"}},{"t":"usc","label":"21 U.S.C. § 355","url":"https://www.law.cornell.edu/uscode/text/21/355","subs":["(b)(1)","(d)","(o)(2)(A)(ii)","(o)(4)","(o)(4)(A)","(o)(4)(B)","(o)(4)(C)","(o)(4)(D)","(o)(4)(E)","(o)(4)(I)"],"stext":{"head":"§355. New drugs","paras":[[0,"(a) Necessity of effective approval of application"],[0,"No person shall introduce or deliver for introduction into interstate commerce any new drug, unless an approval of an application filed pursuant to subsection (b) or (j) is effective with respect to such drug."],[0,"(b) Filing application; contents"],[0,"(1)(A) Any person may file with the Secretary an application with respect to any drug subject to the provisions of subsection (a). Such persons shall submit to the Secretary as part of the application—"],[1,"(i) full reports of investigations which have been made to show whether such drug is safe for use and whether such drug is effective in use;"],[1,"(ii) a full list of the articles used as components of such drug;"],[1,"(iii) a full statement of the composition of such drug;"],[1,"(iv) a full description of the methods used in, and the facilities and controls used for, the manufacture, processing, and packing of such drug;"],[1,"(v) such samples of such drug and of the articles used as components thereof as the Secretary may require;"],[1,"(vi) specimens of the labeling proposed to be used for such drug;"],[1,"(vii) any assessments required under section 355c of this title; and"],[1,"(viii) the patent number and expiration date of each patent for which a claim of patent infringement could reasonably be asserted if a person not licensed by the owner of the patent engaged in the manufacture, use, or sale of the drug, and that—"],[2,"(I) claims the drug for which the applicant submitted the application and is a drug substance (active ingredient) patent or a drug product (formulation or composition) patent; or"],[2,"(II) claims a method of using such drug for which approval is sought or has been granted in the application."],[0,"(B) If an application is filed under this subsection for a drug, and a patent of the type described in subparagraph (A)(viii) is issued after the filing date but before approval of the application, the applicant shall amend the application to include the patent number and expiration date."],[0,"(2) An application submitted under paragraph (1) for a drug for which the investigations described in clause (A) of such paragraph and relied upon by the applicant for approval of the application were not conducted by or for the applicant and for which the applicant has not obtained a right of reference or use from the person by or for whom the investigations were conducted shall also include—"],[1,"(A) a certification, in the opinion of the applicant and to the best of his knowledge, with respect to each patent which claims the drug for which such investigations were conducted or which claims a use for such drug for which the applicant is seeking approval under this subsection and for which information is required to be filed under paragraph (1) or subsection (c)—"],[2,"(i) that such patent information has not been filed,"],[2,"(ii) that such patent has expired,"],[2,"(iii) of the date on which such patent will expire, or"],[2,"(iv) that such patent is invalid or will not be infringed by the manufacture, use, or sale of the new drug for which the application is submitted; and"],[1,"(B) if with respect to the drug for which investigations described in paragraph (1)(A) were conducted information was filed under paragraph (1) or subsection (c) for a method of use patent which does not claim a use for which the applicant is seeking approval under this subsection, a statement that the method of use patent does not claim such a use."],[0,"(3) Notice of opinion that patent is invalid or will not be infringed.—"],[1,"(A) Agreement to give notice.—An applicant that makes a certification described in paragraph (2)(A)(iv) shall include in the application a statement that the applicant will give notice as required by this paragraph."],[1,"(B) Timing of notice.—An applicant that makes a certification described in paragraph (2)(A)(iv) shall give notice as required under this paragraph—"],[2,"(i) if the certification is in the application, not later than 20 days after the date of the postmark on the notice with which the Secretary informs the applicant that the application has been filed; or"],[2,"(ii) if the certification is in an amendment or supplement to the application, at the time at which the applicant submits the amendment or supplement, regardless of whether the applicant has already given notice with respect to another such certification contained in the application or in an amendment or supplement to the application."],[1,"(C) Recipients of notice.—An applicant required under this paragraph to give notice shall give notice to—"],[2,"(i) each owner of the patent that is the subject of the certification (or a representative of the owner designated to receive such a notice); and"],[2,"(ii) the holder of the approved application under this subsection for the drug that is claimed by the patent or a use of which is claimed by the patent (or a representative of the holder designated to receive such a notice)."],[1,"(D) Contents of notice.—A notice required under this paragraph shall—"],[2,"(i) state that an application that contains data from bioavailability or bioequivalence studies has been submitted under this subsection for the drug with respect to which the certification is made to obtain approval to engage in the commercial manufacture, use, or sale of the drug before the expiration of the patent referred to in the certification; and"],[2,"(ii) include a detailed statement of the factual and legal basis of the opinion of the applicant that the patent is invalid or will not be infringed."],[0,"(4)(A) An applicant may not amend or supplement an application referred to in paragraph (2) to seek approval of a drug that is a different drug than the drug identified in the application as submitted to the Secretary."],[0,"(B) With respect to the drug for which such an application is submitted, nothing in this subsection or subsection (c)(3) prohibits an applicant from amending or supplementing the application to seek approval of a different strength."],[0,"(5)(A) The Secretary shall issue guidance for the individuals who review applications submitted under paragraph (1) or under section 262 of title 42, which shall relate to promptness in conducting the review, technical excellence, lack of bias and conflict of interest, and knowledge of regulatory and scientific standards, and which shall apply equally to all individuals who review such applications."],[0,"(B) The Secretary shall meet with a sponsor of an investigation or an applicant for approval for a drug under this subsection or section 262 of title 42 if the sponsor or applicant makes a reasonable written request for a meeting for the purpose of reaching agreement on the design and size—"],[1,"(i)(I) of clinical trials intended to form the primary basis of an effectiveness claim; or"],[1,"(II) in the case where human efficacy studies are not ethical or feasible, of animal and any associated clinical trials which, in combination, are intended to form the primary basis of an effectiveness claim; or"],[1,"(ii) with respect to an application for approval of a biological product under section 262(k) of title 42, of any necessary clinical study or studies."],[0,"The sponsor or applicant shall provide information necessary for discussion and agreement on the design and size of the clinical trials. Minutes of any such meeting shall be prepared by the Secretary and made available to the sponsor or applicant upon request."],[0,"(C) Any agreement regarding the parameters of the design and size of clinical trials of a new drug under this paragraph that is reached between the Secretary and a sponsor or applicant shall be reduced to writing and made part of the administrative record by the Secretary. Such agreement shall not be changed after the testing begins, except—"],[1,"(i) with the written agreement of the sponsor or applicant; or"],[1,"(ii) pursuant to a decision, made in accordance with subparagraph (D) by the director of the reviewing division, that a substantial scientific issue essential to determining the safety or effectiveness of the drug has been identified after the testing has begun."],[0,"(D) A decision under subparagraph (C)(ii) by the director shall be in writing and the Secretary shall provide to the sponsor or applicant an opportunity for a meeting at which the director and the sponsor or applicant will be present and at which the director will document the scientific issue involved."],[0,"(E) The written decisions of the reviewing division shall be binding upon, and may not directly or indirectly be changed by, the field or compliance division personnel unless such field or compliance division personnel demonstrate to the reviewing division why such decision should be modified."],[0,"(F) No action by the reviewing division may be delayed because of the unavailability of information from or action by field personnel unless the reviewing division determines that a delay is necessary to assure the marketing of a safe and effective drug."],[0,"(G) For purposes of this paragraph, the reviewing division is the division responsible for the review of an application for approval of a drug under this subsection or section 262 of title 42 (including all scientific and medical matters, chemistry, manufacturing, and controls)."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/21/355?type=usc&year=mostrecent&link-type=html"},"op":6,"head":"§355. New drugs","tname":"Food and Drugs","by":{"0":"passim","1":"4, 2, 4, 10, 10, 11, 33, 34, 10, 33, 10, 33, 11, 11, 11, 4","3":"passim"}},{"t":"usc","label":"28 U.S.C. § 1254","url":"https://www.law.cornell.edu/uscode/text/28/1254","by":{"0":"2"}},{"t":"reg","label":"21 C.F.R. § 20.1","url":"https://www.ecfr.gov/current/title-21/section-20.1","by":{"0":"52"}},{"t":"reg","label":"21 C.F.R. § 20.2","url":"https://www.ecfr.gov/current/title-21/section-20.2","by":{"0":"52"}},{"t":"reg","label":"21 C.F.R. § 201.57","url":"https://www.ecfr.gov/current/title-21/section-201.57","by":{"0":"3, 10"}},{"t":"reg","label":"21 C.F.R. § 314.70","url":"https://www.ecfr.gov/current/title-21/section-314.70","by":{"0":"4","3":"23"}},{"t":"reg","label":"21 C.F.R. § 314.71","url":"https://www.ecfr.gov/current/title-21/section-314.71","by":{"0":"6"}},{"t":"reg","label":"21 C.F.R. § 314.102","url":"https://www.ecfr.gov/current/title-21/section-314.102","by":{"0":"5, 6, 32, 34","3":"3"}},{"t":"reg","label":"21 C.F.R. § 314.105","url":"https://www.ecfr.gov/current/title-21/section-314.105","by":{"0":"6, 32, 34","3":"3"}},{"t":"reg","label":"21 C.F.R. § 314.110","url":"https://www.ecfr.gov/current/title-21/section-314.110","by":{"0":"6"}},{"t":"reg","label":"21 C.F.R. § 314.125","url":"https://www.ecfr.gov/current/title-21/section-314.125","by":{"0":"4"}},{"t":"reg","label":"71 Fed. Reg. 3922","url":"https://www.govinfo.gov/link/fr/71/3922","by":{"0":"2, 3, 4","1":"2","2":"28"}},{"t":"reg","label":"73 Fed. Reg. 49603","url":"https://www.govinfo.gov/link/fr/73/49603","by":{"0":"10","1":"3"}},{"t":"rule","label":"Fed. R. Civ. P. 56","url":"https://www.law.cornell.edu/rules/frcp/rule_56","by":{"0":"49"}},{"t":"case","label":"Arizona v. Inter Tribal Council of Ariz., Inc.","cite":"570 U.S. 1","y":2013,"id":"2012/12-71","sc":1,"op":1,"sum":"The Court found the National Voter Registration Act preempted other voter registration requirements.","sumSrc":"Oyez","by":{"1":"25"}},{"t":"case","label":"Armour & Co. v. Wantock","cite":"323 U.S. 126","y":1944,"id":"scdb/1944-014","sc":1,"sum":"1. Fireguards employed by a manufacturer of goods for interstate comnerce, held covered by the Fair Labor Standards Act of 1938, as employed in an \"occupation necessary to the production\" of goods for interstate commerce.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"24"}},{"t":"case","label":"Emich Motors Corp. v. General Motors Corp.","cite":"340 U.S. 558","y":1951,"id":"scdb/1950-046","sc":1,"by":{"1":"19"}},{"t":"case","label":"Grogan v. Garner","cite":"498 U.S. 279","y":1991,"id":"1990/89-1149","sc":1,"sum":"Courts should apply the \"preponderance of the evidence\" standard. Justice John Paul Stevens, for a unanimous Supreme Court, wrote that the lack of a specified standard of evidence in section 523(a) implied that Congress had intended the preponderance of the evidence standard to be used.","sumSrc":"Oyez","by":{"1":"24"}},{"t":"case","label":"Landgraf v. USI Film Prods.","cite":"511 U.S. 244","y":1994,"id":"1993/92-757","sc":1,"sum":"Section 102 does not apply to a Title VII case that was pending on appeal when the 1991 Act was enacted.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"24"}},{"t":"case","label":"Perez v. Mortgage Bankers Ass’n","cite":"135 S. Ct. 1199","y":2015,"id":"2014/13-1041","sc":1,"sum":"The Court ruled that federal agencies do not need to engage in a notice-and-comment procedure before significantly altering an interpretation of a rule of agency regulation.","sumSrc":"Oyez","by":{"1":"20"}},{"t":"case","label":"Riegel v. Medtronic, Inc.","cite":"552 U.S. 312","y":2008,"id":"2007/06-179","sc":1,"sum":"The Court, in an 8-1 decision, affirmed the Second Circuit and granted summary judgment in favor of Medtronic. The Court's opinion, written by Justice Antonin Scalia, noted that the MDA pre-empted state common law claims for defective devices such as this one.","sumSrc":"Oyez","by":{"1":"29"}},{"t":"case","label":"Teva Pharm. USA, Inc. v. Sandoz, Inc.","cite":"135 S. Ct. 831","y":2015,"id":"2014/13-854","sc":1,"op":1,"sum":"The Court ruled that a federal appellate court can only overturn a district court’s finding of fact if those findings were determined to be “clearly erroneous.”","sumSrc":"Oyez","by":{"1":"21"}},{"t":"usc","label":"5 U.S.C. § 551","url":"https://www.law.cornell.edu/uscode/text/5/551","subs":["(6)","(7)"],"by":{"1":"18, 18, 18"}},{"t":"usc","label":"5 U.S.C. § 706","url":"https://www.law.cornell.edu/uscode/text/5/706","stext":{"head":"§706. Scope of review","paras":[[0,"To the extent necessary to decision and when presented, the reviewing court shall decide all relevant questions of law, interpret constitutional and statutory provisions, and determine the meaning or applicability of the terms of an agency action. The reviewing court shall—"],[1,"(1) compel agency action unlawfully withheld or unreasonably delayed; and"],[1,"(2) hold unlawful and set aside agency action, findings, and conclusions found to be—"],[2,"(A) arbitrary, capricious, an abuse of discretion, or otherwise not in accordance with law;"],[2,"(B) contrary to constitutional right, power, privilege, or immunity;"],[2,"(C) in excess of statutory jurisdiction, authority, or limitations, or short of statutory right;"],[2,"(D) without observance of procedure required by law;"],[2,"(E) unsupported by substantial evidence in a case subject to sections 556 and 557 of this title or otherwise reviewed on the record of an agency hearing provided by statute; or"],[2,"(F) unwarranted by the facts to the extent that the facts are subject to trial de novo by the reviewing court."],[0,"In making the foregoing determinations, the court shall review the whole record or those parts of it cited by a party, and due account shall be taken of the rule of prejudicial error."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/5/706?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§706. Scope of review","tname":"Government Organization and Employees","by":{"1":"15, 18"}},{"t":"usc","label":"21 U.S.C. § 301","url":"https://www.law.cornell.edu/uscode/text/21/301","stext":{"head":"§301. Short title","paras":[[0,"This chapter may be cited as the Federal Food, Drug, and Cosmetic Act."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/21/301?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§301. Short title","tname":"Food and Drugs","by":{"1":"2","2":"3, 4, 24, 26, 27, 28, 30, 31, 54, 56"}},{"t":"usc","label":"21 U.S.C. § 321","url":"https://www.law.cornell.edu/uscode/text/21/321","stext":{"head":"§321. Definitions; generally","paras":[[0,"For the purposes of this chapter—"],[0,"(a)(1) The term \"State\", except as used in the last sentence of section 372(a) of this title, means any State or Territory of the United States, the District of Columbia, and the Commonwealth of Puerto Rico."],[0,"(2) The term \"Territory\" means any Territory or possession of the United States, including the District of Columbia, and excluding the Commonwealth of Puerto Rico and the Canal Zone."],[0,"(b) The term \"interstate commerce\" means (1) commerce between any State or Territory and any place outside thereof, and (2) commerce within the District of Columbia or within any other Territory not organized with a legislative body."],[0,"(c) The term \"Department\" means Department of Health and Human Services."],[0,"(d) The term \"Secretary\" means the Secretary of Health and Human Services."],[0,"(e) The term \"person\" includes individual, partnership, corporation, and association."],[0,"(f) The term \"food\" means (1) articles used for food or drink for man or other animals, (2) chewing gum, and (3) articles used for components of any such article."],[0,"(g)(1) The term \"drug\" means (A) articles recognized in the official United States Pharmacopoeia,1 official Homoeopathic Pharmacopoeia of the United States, or official National Formulary, or any supplement to any of them; and (B) articles intended for use in the diagnosis, cure, mitigation, treatment, or prevention of disease in man or other animals; and (C) articles (other than food) intended to affect the structure or any function of the body of man or other animals; and (D) articles intended for use as a component of any article specified in clause (A), (B), or (C). A food or dietary supplement for which a claim, subject to sections 343(r)(1)(B) and 343(r)(3) of this title or sections 343(r)(1)(B) and 343(r)(5)(D) of this title, is made in accordance with the requirements of section 343(r) of this title is not a drug solely because the label or the labeling contains such a claim. A food, dietary ingredient, or dietary supplement for which a truthful and not misleading statement is made in accordance with section 343(r)(6) of this title is not a drug under clause (C) solely because the label or the labeling contains such a statement."],[0,"(2) The term \"counterfeit drug\" means a drug which, or the container or labeling of which, without authorization, bears the trademark, trade name, or other identifying mark, imprint, or device, or any likeness thereof, of a drug manufacturer, processor, packer, or distributor other than the person or persons who in fact manufactured, processed, packed, or distributed such drug and which thereby falsely purports or is represented to be the product of, or to have been packed or distributed by, such other drug manufacturer, processor, packer, or distributor."],[0,"(h)(1) The term \"device\" (except when used in paragraph (n) of this section and in sections 331(i), 343(f), 352(c), and 362(c) of this title) means an instrument, apparatus, implement, machine, contrivance, implant, in vitro reagent, or other similar or related article, including any component, part, or accessory, which is—"],[1,"(A) recognized in the official National Formulary, or the United States Pharmacopeia, or any supplement to them,"],[1,"(B) intended for use in the diagnosis of disease or other conditions, or in the cure, mitigation, treatment, or prevention of disease, in man or other animals, or"],[1,"(C) intended to affect the structure or any function of the body of man or other animals, and"],[0,"which does not achieve its primary intended purposes through chemical action within or on the body of man or other animals and which is not dependent upon being metabolized for the achievement of its primary intended purposes. The term \"device\" does not include software functions excluded pursuant to section 360j(o) of this title."],[0,"(2) The term \"counterfeit device\" means a device which, or the container, packaging, or labeling of which, without authorization, bears a trademark, trade name, or other identifying mark or imprint, or any likeness thereof, or is manufactured using a design, of a device manufacturer, processor, packer, or distributor other than the person or persons who in fact manufactured, processed, packed, or distributed such device and which thereby falsely purports or is represented to be the product of, or to have been packed or distributed by, such other device manufacturer, processor, packer, or distributor."],[0,"(i) The term \"cosmetic\" means (1) articles intended to be rubbed, poured, sprinkled, or sprayed on, introduced into, or otherwise applied to the human body or any part thereof for cleansing, beautifying, promoting attractiveness, or altering the appearance, and (2) articles intended for use as a component of any such articles; except that such term shall not include soap."],[0,"(j) The term \"official compendium\" means the official United States Pharmacopoeia, official Homoeopathic Pharmacopoeia of the United States, official National Formulary, or any supplement to any of them."],[0,"(k) The term \"label\" means a display of written, printed, or graphic matter upon the immediate container of any article; and a requirement made by or under authority of this chapter that any word, statement, or other information appear on the label shall not be considered to be complied with unless such word, statement, or other information also appears on the outside container or wrapper, if any there be, of the retail package of such article, or is easily legible through the outside container or wrapper."],[0,"(l) The term \"immediate container\" does not include package liners."],[0,"(m) The term \"labeling\" means all labels and other written, printed, or graphic matter (1) upon any article or any of its containers or wrappers, or (2) accompanying such article."],[0,"(n) If an article is alleged to be misbranded because the labeling or advertising is misleading, then in determining whether the labeling or advertising is misleading there shall be taken into account (among other things) not only representations made or suggested by statement, word, design, device, or any combination thereof, but also the extent to which the labeling or advertising fails to reveal facts material in the light of such representations or material with respect to consequences which may result from the use of the article to which the labeling or advertising relates under the conditions of use prescribed in the labeling or advertising thereof or under such conditions of use as are customary or usual."],[0,"(o) The representation of a drug, in its labeling, as an antiseptic shall be considered to be a representation that it is a germicide, except in the case of a drug purporting to be, or represented as, an antiseptic for inhibitory use as a wet dressing, ointment, dusting powder, or such other use as involves prolonged contact with the body."],[0,"(p) The term \"new drug\" means—"],[1,"(1) Any drug (except a new animal drug or an animal feed bearing or containing a new animal drug) the composition of which is such that such drug is not generally recognized, among experts qualified by scientific training and experience to evaluate the safety and effectiveness of drugs, as safe and effective for use under the conditions prescribed, recommended, or suggested in the labeling thereof, except that such a drug not so recognized shall not be deemed to be a \"new drug\" if at any time prior to June 25, 1938, it was subject to the Food and Drugs Act of June 30, 1906, as amended, and if at such time its labeling contained the same representations concerning the conditions of its use; or"],[1,"(2) Any drug (except a new animal drug or an animal feed bearing or containing a new animal drug) the composition of which is such that such drug, as a result of investigations to determine its safety and effectiveness for use under such conditions, has become so recognized, but which has not, otherwise than in such investigations, been used to a material extent or for a material time under such conditions."],[0,"(q)(1)(A) Except as provided in clause (B), the term \"pesticide chemical\" means any substance that is a pesticide within the meaning of the Federal Insecticide, Fungicide, and Rodenticide Act [7 U.S.C. 136 et seq.], including all active and inert ingredients of such pesticide. Notwithstanding any other provision of law, the term \"pesticide\" within such meaning includes ethylene oxide and propylene oxide when such substances are applied on food."],[0,"(B) In the case of the use, with respect to food, of a substance described in clause (A) to prevent, destroy, repel, or mitigate microorganisms (including bacteria, viruses, fungi, protozoa, algae, and slime), the following applies for purposes of clause (A):"],[1,"(i) The definition in such clause for the term \"pesticide chemical\" does not include the substance if the substance is applied for such use on food, or the substance is included for such use in water that comes into contact with the food, in the preparing, packing, or holding of the food for commercial purposes. The substance is not excluded under this subclause from such definition if the substance is ethylene oxide or propylene oxide, and is applied for such use on food. The substance is not so excluded if the substance is applied for such use on a raw agricultural commodity, or the substance is included for such use in water that comes into contact with the commodity, as follows:"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/21/321?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§321. Definitions; generally","tname":"Food and Drugs","by":{"1":"2"}},{"t":"usc","label":"21 U.S.C. § 352","url":"https://www.law.cornell.edu/uscode/text/21/352","stext":{"head":"§352. Misbranded drugs and devices","paras":[[0,"A drug or device shall be deemed to be misbranded—"],[0,"(a) False or misleading label"],[0,"(1) If its labeling is false or misleading in any particular. Health care economic information provided to a payor, formulary committee, or other similar entity with knowledge and expertise in the area of health care economic analysis, carrying out its responsibilities for the selection of drugs or devices for coverage or reimbursement, shall not be considered to be false or misleading under this paragraph if the health care economic information relates to an indication approved under section 355, 360(k), 360c(f)(2), or 360e of this title or section 262 of title 42 for such drug or device, is based on competent and reliable scientific evidence, and includes, where applicable, a conspicuous and prominent statement describing any material differences between the health care economic information and the labeling approved for the drug or device under section 355, 360(k), 360c(f)(2), or 360e of this title or section 262 of title 42. The requirements set forth in section 355, 360(k), 360c(f)(2), or 360e of this title or section 262 of title 42 shall not apply to health care economic information provided to such a payor, committee, or entity in accordance with this paragraph. Information that is relevant to the substantiation of the health care economic information presented pursuant to this paragraph shall be made available to the Secretary upon request."],[0,"(2)(A) For purposes of this paragraph,1 the term \"health care economic information\" means any analysis (including the clinical data, inputs, clinical or other assumptions, methods, results, and other components underlying or comprising the analysis) that identifies, measures, or describes the economic consequences, which may be based on the separate or aggregated clinical consequences of the represented health outcomes, of the use of a drug or device. Such analysis may be comparative to the use of another drug or device, to another health care intervention, or to no intervention."],[0,"(B) Such term does not include any analysis that relates only to an indication that is not approved under section 355, 360(k), 360c(f)(2), or 360e of this title or section 262 of title 42 for such drug or device."],[0,"(b) Package form; contents of label"],[0,"If in package form unless it bears a label containing (1) the name and place of business of the manufacturer, packer, or distributor; and (2) an accurate statement of the quantity of the contents in terms of weight, measure, or numerical count: Provided, That under clause (2) of this paragraph reasonable variations shall be permitted, and exemptions as to small packages shall be established, by regulations prescribed by the Secretary."],[0,"(c) Prominence of information on label"],[0,"If any word, statement, or other information required by or under authority of this chapter to appear on the label or labeling is not prominently placed thereon with such conspicuousness (as compared with other words, statements, designs, or devices, in the labeling) and in such terms as to render it likely to be read and understood by the ordinary individual under customary conditions of purchase and use."],[0,"(d) Repealed. Pub. L. 105–115, title I, §126(b), Nov. 21, 1997, 111 Stat. 2327"],[0,"(e) Designation of drugs or devices by established names"],[0,"(1)(A) If it is a drug, unless its label bears, to the exclusion of any other nonproprietary name (except the applicable systematic chemical name or the chemical formula)—"],[1,"(i) the established name (as defined in subparagraph (3)) of the drug, if there is such a name;"],[1,"(ii) the established name and quantity or, if determined to be appropriate by the Secretary, the proportion of each active ingredient, including the quantity, kind, and proportion of any alcohol, and also including whether active or not the established name and quantity or if determined to be appropriate by the Secretary, the proportion of any bromides, ether, chloroform, acetanilide, acetophenetidin, amidopyrine, antipyrine, atropine, hyoscine, hyoscyamine, arsenic, digitalis, digitalis glucosides, mercury, ouabain, strophanthin, strychnine, thyroid, or any derivative or preparation of any such substances, contained therein, except that the requirement for stating the quantity of the active ingredients, other than the quantity of those specifically named in this subclause, shall not apply to nonprescription drugs not intended for human use; and"],[1,"(iii) the established name of each inactive ingredient listed in alphabetical order on the outside container of the retail package and, if determined to be appropriate by the Secretary, on the immediate container, as prescribed in regulation promulgated by the Secretary, except that nothing in this subclause shall be deemed to require that any trade secret be divulged, and except that the requirements of this subclause with respect to alphabetical order shall apply only to nonprescription drugs that are not also cosmetics and that this subclause shall not apply to nonprescription drugs not intended for human use."],[0,"(B) For any prescription drug the established name of such drug or ingredient, as the case may be, on such label (and on any labeling on which a name for such drug or ingredient is used) shall be printed prominently and in type at least half as large as that used thereon for any proprietary name or designation for such drug or ingredient, except that to the extent that compliance with the requirements of subclause (ii) or (iii) of clause (A) or this clause is impracticable, exemptions shall be established by regulations promulgated by the Secretary."],[0,"(2) If it is a device and it has an established name, unless its label bears, to the exclusion of any other nonproprietary name, its established name (as defined in subparagraph (4)) prominently printed in type at least half as large as that used thereon for any proprietary name or designation for such device, except that to the extent compliance with the requirements of this subparagraph is impracticable, exemptions shall be established by regulations promulgated by the Secretary."],[0,"(3) As used in subparagraph (1), the term \"established name\", with respect to a drug or ingredient thereof, means (A) the applicable official name designated pursuant to section 358 of this title, or (B), if there is no such name and such drug, or such ingredient, is an article recognized in an official compendium, then the official title thereof in such compendium, or (C) if neither clause (A) nor clause (B) of this subparagraph applies, then the common or usual name, if any, of such drug or of such ingredient, except that where clause (B) of this subparagraph applies to an article recognized in the United States Pharmacopeia and in the Homoeopathic Pharmacopoeia under different official titles, the official title used in the United States Pharmacopeia shall apply unless it is labeled and offered for sale as a homoeopathic drug, in which case the official title used in the Homoeopathic Pharmacopoeia shall apply."],[0,"(4) As used in subparagraph (2), the term \"established name\" with respect to a device means (A) the applicable official name of the device designated pursuant to section 358 of this title, (B) if there is no such name and such device is an article recognized in an official compendium, then the official title thereof in such compendium, or (C) if neither clause (A) nor clause (B) of this subparagraph applies, then any common or usual name of such device."],[0,"(f) Directions for use and warnings on label"],[0,"Unless its labeling bears (1) adequate directions for use; and (2) such adequate warnings against use in those pathological conditions or by children where its use may be dangerous to health, or against unsafe dosage or methods or duration of administration or application, in such manner and form, as are necessary for the protection of users, except that where any requirement of clause (1) of this paragraph, as applied to any drug or device, is not necessary for the protection of the public health, the Secretary shall promulgate regulations exempting such drug or device from such requirement. Required labeling for prescription devices intended for use in health care facilities or by a health care professional and required labeling for in vitro diagnostic devices intended for use by health care professionals or in blood establishments may be made available solely by electronic means, provided that the labeling complies with all applicable requirements of law, and that the manufacturer affords such users the opportunity to request the labeling in paper form, and after such request, promptly provides the requested information without additional cost."],[0,"(g) Representations as recognized drug; packing and labeling; inconsistent requirements for designation of drug"],[0,"If it purports to be a drug the name of which is recognized in an official compendium, unless it is packaged and labeled as prescribed therein. The method of packing may be modified with the consent of the Secretary. Whenever a drug is recognized in both the United States Pharmacopoeia and the Homoeopathic Pharmacopoeia of the United States, it shall be subject to the requirements of the United States Pharmacopoeia with respect to packaging and labeling unless it is labeled and offered for sale as a homoeopathic drug, in which case it shall be subject to the provisions of the Homoeopathic Pharmacopoeia of the United States, and not those of the United States Pharmacopoeia, except that in the event of inconsistency between the requirements of this paragraph and those of paragraph (e) as to the name by which the drug or its ingredients shall be designated, the requirements of paragraph (e) shall prevail."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/21/352?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§352. Misbranded drugs and devices","tname":"Food and Drugs","by":{"1":"2"}},{"t":"rule","label":"Fed. R. Evid. 301","url":"https://www.law.cornell.edu/rules/fre/rule_301","by":{"1":"25"}},{"t":"case","label":"Anderson v. Liberty Lobby, Inc.","cite":"477 U.S. 242","y":1986,"id":"1985/84-1602","sc":1,"sum":"In a 6-to-3 opinion, the Court held that the purpose of summary judgments is to determine if the evidence is so one-sided that a party should prevail as a matter of law. Summary judgments will not lie if there is a sufficient likelihood that a reasonable jury would return a verdict favorable to the nonmoving party.","sumSrc":"Oyez","by":{"2":"22, 57"}},{"t":"case","label":"Anza v. Ideal Steel Supply Corp.","cite":"547 U.S. 451","y":2006,"id":"2005/04-433","sc":1,"sum":"The ninth member - Justice Clarence Thomas - wrote that while he disagreed with the other justices' concern about directness, he too would have ruled in National's favor because the case had nothing to do with organized crime, RICO's original target.","sumSrc":"Oyez","by":{"2":"23"}},{"t":"case","label":"Blood Balm Co. v. Cooper","cite":"10 S.E. 118","y":1889,"court":"Ga.","url":"https://www.courtlistener.com/c/S.E./10/118/","by":{"2":"3"}},{"t":"case","label":"Brown v. Hotel & Rest. Emps.","cite":"468 U.S. 491","y":1984,"id":"1983/83-498","sc":1,"sum":"Section 9 of the New Jersey Casino Control Act requires annual registration of unions representing persons employed in casinos or casino hotels, and provides that a union may be prohibited from receiving dues from such employees and from administering any pension or welfare funds if any union officer is disqualified under the criteria contained in §86 for the licensing of various entities and persons. Those criteria …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"28"}},{"t":"case","label":"City of Monterey v. Del Monte Dunes at Monterey, Ltd.","cite":"526 U.S. 687","y":1999,"id":"1998/97-1235","sc":1,"sum":"The Court held, in an opinion authored by Justice Anthony M. Kennedy, that property owners who file a Section 1983 civil rights suit seeking compensation for an alleged taking of their property can have a jury trial in some circumstances. \"[T]he disputed questions were whether the government had denied a constitutional right outside the bounds of its authority, and, if so, the extent of any resulting damages.\" Justice Kennedy then added: \"These were questions for the jury.\".","sumSrc":"Oyez","by":{"2":"26, 51, 53"}},{"t":"case","label":"Dolin v. GlaxoSmithKline LLC","cite":"901 F.3d 803","y":2018,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/901/803/","by":{"2":"43, 44"}},{"t":"case","label":"E.I. Du Pont de Nemours & Co. v. Smiley","cite":"138 S. Ct. 2563","y":2018,"url":"https://www.courtlistener.com/c/S.%20Ct./138/2563/","sc":1,"by":{"2":"46","3":"16"}},{"t":"case","label":"Fisher v. Golladay","cite":"38 Mo. App. 531","y":1889,"url":"https://www.courtlistener.com/c/Mo.%20App./38/531/","by":{"2":"3"}},{"t":"case","label":"Freightliner Corp. v. Myrick","cite":"514 U.S. 280","y":1995,"id":"1994/94-286","sc":1,"sum":"In separate state common-law suits, respondents alleged that the absence of an antilock braking system (ABS) in tractor-trailers manufactured by petitioners constituted a negligent design defect that caused accidents injuring one respondent and killing another's spouse. The District Court granted summary judgments for petitioners, holding that respondents' claims were pre-empted by the National Traffic and Motor …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"29, 56"}},{"t":"case","label":"Gobeille v. Liberty Mut. Ins. Co.","cite":"136 S. Ct. 936","y":2016,"id":"2015/14-181","sc":1,"sum":"The Court determined that the reporting requirements of the Employee Retirement Income Security Act of 1974 (ERISA) preempt a Vermont state statute regarding reporting requirements as applied to a self-insured employee health plan.","sumSrc":"Oyez","by":{"2":"28"}},{"t":"case","label":"Halloran v. Parke, Davis & Co.","cite":"280 N.Y.S. 58","y":1935,"court":"App. Div.","url":"https://www.courtlistener.com/c/N.Y.S./280/58/","by":{"2":"3"}},{"t":"case","label":"Hines v. Davidowitz","cite":"312 U.S. 52","y":1941,"id":"scdb/1940-064","sc":1,"sum":"1. Applicable legislation enacted while the case was pending on appeal will be enforced by the appellate court.","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"28"}},{"t":"case","label":"Horstkoetter v. Department of Pub. Safety","cite":"159 F.3d 1265","y":1998,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.3d/159/1265/","by":{"2":"53"}},{"t":"case","label":"Hughes v. Talen Energy Mktg., LLC","cite":"136 S. Ct. 1288","y":2016,"id":"2015/14-614","sc":1,"sum":"The Court determined that the Federal Power Act preempted state regulation of utility contracts and sales.","sumSrc":"Oyez","by":{"2":"29"}},{"t":"case","label":"Kurns v. Railroad Friction Prods. Corp.","cite":"565 U.S. 625","y":2012,"id":"2011/10-879","sc":1,"sum":"The Court held that the Locomotive Inspection Act preempts state law design defect claims and state law failure to warn claims.","sumSrc":"Oyez","by":{"2":"27-28"}},{"t":"case","label":"Medtronic, Inc. v. Lohr","cite":"518 U.S. 470","y":1996,"id":"1995/95-754","sc":1,"sum":"The Court held that the Court of Appeals decision was reversed insofar as it held that any of the claims were pre-empted and affirmed insofar as it rejected any pre-emption defense. In a 9-0 vote, the Court allowed the lawsuit based on alleged defects in the pacemaker's design to proceed.","sumSrc":"Oyez","by":{"2":"28"}},{"t":"case","label":"Richards v. Jefferson Cty.","cite":"517 U.S. 793","y":1996,"id":"1995/95-386","sc":1,"op":3,"sum":"Authored by Justice John Paul Stevens, the Court ruled that because Richards and others received neither notice of, nor sufficient representation in, the Bedingfield litigation, that adjudication, as a matter of federal due process, may not bind them and thus cannot bar them from challenging an allegedly unconstitutional deprivation of their property.","sumSrc":"Oyez","by":{"2":"58"}},{"t":"case","label":"Scott v. Harris","cite":"550 U.S. 372","y":2007,"id":"2006/05-1631","sc":1,"sum":"The Court ruled 8-1 that Scott's actions were reasonable under the Fourth Amendment. The opinion by Justice Antonin Scalia relied heavily on a videotape of the car chase, which it said contradicted the plaintiff's claim that he was driving responsibly even while being pursued by the police.","sumSrc":"Oyez","by":{"2":"53"}},{"t":"case","label":"Skidmore v. Swift & Co.","cite":"323 U.S. 134","y":1944,"id":"1940-1955/12","sc":1,"sum":"The Court held that there was no reason that time spent waiting could not also be time spent working, especially in cases in which the conditions of employment involve waiting time. Although it can be difficult to determine the facts of a case and whether the activity in question constitutes work, Congress granted the courts the authority to do so.","sumSrc":"Oyez","by":{"2":"46"}},{"t":"case","label":"Taylor v. Sturgell","cite":"553 U.S. 880","y":2008,"id":"2007/07-371","sc":1,"sum":"Writing for a unanimous Court, Justice Ruth Bader Ginsburg held that such \"nonparty preclusion\" runs up against the \"deep-rooted historic tradition that everyone should have his own day in court.\" Virtual representation should only be applied rarely and under certain exceptions to the general rule, none of which the Court found applicable in this case.","sumSrc":"Oyez","by":{"2":"58"}},{"t":"case","label":"Thomas v. Winchester","cite":"6 N.Y. 397","y":1852,"url":"https://www.courtlistener.com/c/N.Y./6/397/","by":{"2":"3"}},{"t":"case","label":"United States v. George S. Bush & Co.","cite":"310 U.S. 371","y":1940,"id":"scdb/1939-072","sc":1,"sum":"The President, acting on a report and recommendation of the Tariff Commission pursuant to the flexible tariff provisions of the Tariff Act of 1930, proclaimed an increase of duty on a Japanese product, to equalize the difference between Japanese and domestic costs of production. In fixing the increase, foreign cost of production was determined, under § 336 (e), on the \"weighted average of the invoice prices or …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"32","3":"6"}},{"t":"const","label":"Amendment I","clauses":[["establishment","Establishment Clause"],["free-exercise","Free Exercise Clause"],["free-speech","Free Speech Clause"],["free-press","Free Press Clause"],["assembly-petition","Assembly, Petition and Association"]],"text":"Congress shall make no law respecting an establishment of religion, or prohibiting the free exercise thereof; or abridging the freedom of speech, or of the press; or the right of the people peaceably to assemble, and to petition the Government for a redress of grievances.","by":{"2":"53"}},{"t":"const","label":"Amendment IV","clauses":[["fourth-amendment","Fourth Amendment"]],"text":"The right of the people to be secure in their persons, houses, papers, and effects, against unreasonable searches and seizures, shall not be violated, and no Warrants shall issue, but upon probable cause, supported by Oath or affirmation, and particularly describing the place to be searched, and the persons or things to be seized.","by":{"2":"53"}},{"t":"const","label":"Amendment VII","clauses":[["seventh-amendment","Seventh Amendment (Civil Jury)"]],"text":"In Suits at common law, where the value in controversy shall exceed twenty dollars, the right of trial by jury shall be preserved, and no fact tried by a jury, shall be otherwise re-examined in any Court of the United States, than according to the rules of the common law.","by":{"2":"51"}},{"t":"usc","label":"5 U.S.C. § 701","url":"https://www.law.cornell.edu/uscode/text/5/701","by":{"2":"46"}},{"t":"law","label":"Pub. L. No. 87-781","url":"https://www.govinfo.gov/link/statute/76/780","by":{"2":"3-4"}},{"t":"law","label":"Pub. L. No. 110-85","url":"https://www.govinfo.gov/link/plaw/110/public/85","by":{"2":"6, 7, 24, 31, 32, 33, 34"}},{"t":"reg","label":"ADMINISTRATIVE MATERIALS, 30 Fed. Reg. 993","url":"https://www.govinfo.gov/link/fr/30/993","by":{"2":"4"}},{"t":"reg","label":"73 Fed. Reg. 39,588","url":"https://www.govinfo.gov/link/fr/73/39588","by":{"2":"6, 25"}},{"t":"case","label":"Coventry Health Care of Mo., Inc. v. Nevils","cite":"137 S. Ct. 1190","y":2017,"id":"2016/16-149","sc":1,"sum":"The Court determined that the Federal Employees Health Benefits Act (FEHBA) preempts state laws that prohibit insurance companies from claiming the proceeds of personal injury settlements pursuant to their contracts, and the express preemption clause of the FEHBA does not violate the Supremacy Clause.","sumSrc":"Oyez","by":{"3":"8"}},{"t":"case","label":"Murphy v. Smith","cite":"138 S. Ct. 784","y":2018,"id":"2017/16-1067","sc":1,"sum":"A case in which the Court interpreted the parenthetical phrase “not to exceed 25 percent,” as used in 42 U.S.C. § 1997e(d)(2), to mean exactly 25 percent, thereby precluding the district court from exercising its discretion to allocate a lower percentage of the damage award to attorney's fees.","sumSrc":"Oyez","by":{"3":"6"}}]};